package weeklyassignments;

public class Assignment2_EmployeeDetails {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		/*Create a Java program to store and print the following employee details:
			•	Employee ID
			•	Age
			•	Salary
			•	Department Initial
			•	Whether the employee is permanent
			Use appropriate primitive data types.*/

		int employeeId=1001;
		System.out.println("Employee Id:"+employeeId);
		byte age=28;
		System.out.println("Age:"+age);
		double salary=55000.50;
		System.out.println("Salary:"+salary);
		char departmentInitial='T';
		System.out.println("Department:"+departmentInitial);
		boolean permanent=true;
		System.out.println("Permanent:"+permanent);
		
	}

}
